manifest=dict(generator_sha256=sha(Path(__file__).read_bytes()),requested_parts=args.parts,maximum_full_stage_sql_bytes=max(f['bytes'] for f in files if f['kind']=='source_only_no_business_effect'),full_sql_byte_limit=100000,status='PARAMETERIZED_PRIVATE_PROPOSALS_NOT_APPLIED_NOT_RUNTIME_QUALIFIED',schema=schema,source_path=args.source,source_bytes=len(source),source_sha256=args.sha256,executable_bytes=len(executable),executable_sha256=sha(executable),removed_tokens=[dict(start_byte=lo,end_byte=hi,deleted=source[lo:hi].decode()) for lo,hi in bounds],ast_equality=True,plain_utf8_parts=args.parts,maximum_part_bytes=max(map(len,parts)),source_only_registrations=args.parts,effect_loader_registrations=1,separate_child_effect_entries_claimed=False,files=files,qualification_required=['staged_first_commit','restaged_same_database_replay','bad_part_refusal','unknown_catalog_metadata_refusal','late_forced_failure_restores_both_transport_and_all_eight_effects'],notes=['Exact source hash mandatory; regenerate after any frozen-source change.','Proposal names are not CLI migration names; actual new migrations require official CLI creation.','No actual DDL, DB business calls, or native fixture collection performed by this generator.','Derived row and array types retain PostgreSQL default type ACL, but no application schema access or table privileges; strict type ownership and absence of explicit type ACL pinned.'])
(out/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print(json.dumps(dict(source_sha256=args.sha256,source_bytes=len(source),maximum_part_bytes=manifest['maximum_part_bytes'],source_stage_count=args.parts,loader_bytes=len(loader.encode()),manifest_sha256=sha((out/'manifest.json').read_bytes()))))
